1	package net.officefloor.hq.app;
2	
3	import java.util.regex.Pattern;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.web.bind.annotation.RequestBody;
6	
7	/**
8	 * {@code POST /api/contacts} — add a contact (name, email, role) to a client and return the created
9	 * row. Wired by {@code officefloor/rest/api/contacts.POST.yml}. The client must exist; the create is
10	 * audited through {@link Audit}.
11	 */
12	public class ContactsPost {
13	
14	    // Every contact must carry a proper email. Mirror of the UI check
15	    // (ClientContactsPanel.isValidEmail) so a request that bypasses the form is still rejected
16	    // before any row or audit record is written.
17	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
18	
19	    public void service(@RequestBody NewContact body, ContactRepository contacts,
20	            ClientRepository clients, Audit audit, ObjectResponse<Contact> response) {
21	        String name = body.getName() == null ? "" : body.getName().trim();
22	        if (name.isEmpty()) {
23	            throw new IllegalArgumentException("a contact requires a name");
24	        }
25	        String email = body.getEmail() == null ? "" : body.getEmail().trim();
26	        if (!EMAIL.matcher(email).matches()) {
27	            throw new IllegalArgumentException("a contact requires a valid email address");
28	        }
29	        String role = body.getRole() == null ? "" : body.getRole().trim();
30	        if (role.isEmpty()) {
31	            throw new IllegalArgumentException("a contact requires a role");
32	        }
33	        Long clientId = body.getClientId();
34	        Client client = clientId == null ? null : clients.findById(clientId).orElse(null);
35	        if (client == null) {
36	            throw new IllegalArgumentException("a contact requires an existing client");
37	        }
38	        Contact contact = new Contact();
39	        contact.setClientId(clientId);
40	        contact.setName(name);
41	        contact.setEmail(email);
42	        contact.setRole(role);
43	        Contact saved = contacts.save(contact);
44	        audit.record("CONTACT_CREATED id=" + saved.getId() + " name=" + saved.getName()
